test('guarded source digest preserves raw physical EOL bytes and the public fingerprint shape',async()=>{
 const subject=await import('./backend-release-admission'),root=await mkdtemp(join(tmpdir(),'cuevo-raw-source-digest-')),hash=(value:string|Uint8Array)=>createHash('sha256').update(value).digest('hex');
 try{
  for(const[name,bytes]of [['.gitattributes','* text eol=lf\n'],['README.md','Raw source\n'],['a-source.ts','export default 1;\n'],['Z-source.ts','export default 2;\n'],['a_source.ts','export default 3;\n']])await writeFile(join(root,name),bytes);
  git(root,'init','--quiet');git(root,'add','.');git(root,'-c','user.name=Fixture','-c','user.email=fixture@example.invalid','-c','commit.gpgsign=false','commit','--quiet','-m','raw source');
  const releaseSha=git(root,'rev-parse','HEAD'),treeSha=git(root,'rev-parse','HEAD^{tree}'),tree=execFileSync('git',['-C',root,'ls-tree','-r','-z',releaseSha]),fingerprints={sourceManifestSha256:hash(tree),diffSha256:hash('')},expected={releaseSha,treeSha,baseSha:releaseSha,fingerprints},paths=git(root,'ls-tree','-r','--name-only',releaseSha).split('\n');
  const rawDigest=()=>hash(JSON.stringify(paths.map(path=>({path,sha256:hash(readFileSync(join(root,path)))})).sort((a,b)=>a.path<b.path?-1:a.path>b.path?1:0)));
  const initial=await subject.readBackendReleaseSourceEvidenceAndGuard(root,expected);assert.deepEqual(initial.proof,fingerprints);assert.equal((initial as typeof initial&{physicalDigest?:string}).physicalDigest,rawDigest(),'The guarded reader returns the digest of its already admitted raw physical bytes');initial.finalPhysical();
  await writeFile(join(root,'README.md'),'Raw source\r\n');
  if(process.platform==='win32'){
   const normalized=await subject.readBackendReleaseSourceEvidenceAndGuard(root,expected);assert.deepEqual(normalized.proof,fingerprints);assert.equal((normalized as typeof normalized&{physicalDigest?:string}).physicalDigest,rawDigest());assert.notEqual((normalized as typeof normalized&{physicalDigest?:string}).physicalDigest,(initial as typeof initial&{physicalDigest?:string}).physicalDigest,'Normalized Git equality never replaces the raw physical digest');normalized.finalPhysical();
   git(root,'update-index','--assume-unchanged','README.md');await writeFile(join(root,'README.md'),'Changed after the raw digest\r\n');assert.throws(normalized.finalPhysical,'Late assumed-unchanged bytes still invalidate the guard');
  }else await assert.rejects(subject.readBackendReleaseSourceEvidenceAndGuard(root,expected),'Non-Windows physical bytes must equal original Git bytes exactly');
 }finally{await rm(root,{recursive:true,force:true});}
});
/** Wrapper isolation only. Original compressed source/runtime archive readers
 * are verified by their own genuine Git/ZIP owner suites. */
async function controlledProof(value:unknown,github:(path:string)=>Promise<unknown>,schema:boolean,artifact?:unknown){
 if(boundary.unknown)throw Error('Controlled canonical boundary requires review');
 if(schema)boundary.schema++;else boundary.runtime++;
 const run=value as {id:number;run_attempt:number;head_sha:string;repository:{full_name:string}};
 assert.match(run.head_sha,/^[a-f0-9]{40}$/);assert.equal(run.repository.full_name,'owner/repo');assert.equal(run.id,31);assert.equal(run.run_attempt,2);
 const current=await github('actions/runs/'+run.id)as typeof run;assert.equal(current.run_attempt,run.run_attempt);assert.equal(current.head_sha,run.head_sha);
 const page=await github(`actions/runs/${run.id}/attempts/${run.run_attempt}/jobs?per_page=100&page=1`)as {total_count:number;jobs:{name:string;run_id:number;run_attempt:number;head_sha:string;status:string;conclusion:string;steps:{name:string;conclusion:string}[]}[]};
 assert.equal(page.total_count,page.jobs.length);const contracts={...ciSourceJobs,'database-checks':ciDatabaseJob,...(schema?{}:ciRuntimeJobs)};
 for(const[name,job]of Object.entries(contracts)){const matched=page.jobs.filter(row=>row.name===name);assert.equal(matched.length,1);const row=matched[0];assert.equal(row.run_id,run.id);assert.equal(row.run_attempt,run.run_attempt);assert.equal(row.head_sha,run.head_sha);assert.equal(row.status,'completed');assert.equal(row.conclusion,'success');assert.deepEqual(row.steps.map(step=>step.name),job.steps.map(step=>'name'in step?step.name:'Run '+('uses'in step?step.uses:step.run)));assert.ok(row.steps.every(step=>step.conclusion==='success'));}
 for(const name of ['codeql','secret-scan',...(schema?[]:['required'])])assert.equal(page.jobs.find(row=>row.name===name)?.conclusion,'success');
 if(artifact!==undefined)assert.equal(typeof artifact,'function');
 const proof={runAttempt:run.run_attempt,jobsSha256:createHash('sha256').update(canonicalReleaseExecutionJson({run:{id:run.id,run_attempt:run.run_attempt,head_sha:run.head_sha,repository:run.repository},jobs:page.jobs.filter(row=>Object.hasOwn(contracts,row.name)||['codeql','secret-scan',...(schema?[]:['required'])].includes(row.name))})).digest('hex')};await boundary.afterProof?.();return proof;
}
const readCanonicalRuntimeJobs=(value:unknown,github:(path:string)=>Promise<unknown>,artifact?:unknown)=>controlledProof(value,github,false,artifact);
async function readCanonicalRuntimeJobsAndGuard(value:unknown,github:(path:string)=>Promise<unknown>,artifact?:unknown){const proof=await readCanonicalRuntimeJobs(value,github,artifact),run=value as{id:number;run_attempt:number;head_sha:string},path=`actions/runs/${run.id}/attempts/${run.run_attempt}/jobs?per_page=100&page=1`,original=canonicalReleaseExecutionJson(await github(path));return{proof,refreshOriginalMetadata:async()=>{assert.equal(canonicalReleaseExecutionJson(await github(path)),original);const current=await github('actions/runs/'+run.id)as typeof run;assert.equal(current.run_attempt,run.run_attempt);assert.equal(current.head_sha,run.head_sha);},assertOriginalValidity:()=>{if(boundary.expired)throw Error('Original canonical artifact expired');}};}
const readCanonicalSchemaJobs=(value:unknown,github:(path:string)=>Promise<unknown>,artifact?:unknown)=>controlledProof(value,github,true,artifact);
async function readCanonicalSchemaJobsAndGuard(value:unknown,github:(path:string)=>Promise<unknown>,artifact?:unknown){const proof=await readCanonicalSchemaJobs(value,github,artifact),run=value as{id:number;run_attempt:number;head_sha:string},path=`actions/runs/${run.id}/attempts/${run.run_attempt}/jobs?per_page=100&page=1`,original=canonicalReleaseExecutionJson(await github(path));return{proof,refreshOriginalMetadata:async()=>{assert.equal(canonicalReleaseExecutionJson(await github(path)),original);const current=await github('actions/runs/'+run.id)as typeof run;assert.equal(current.run_attempt,run.run_attempt);assert.equal(current.head_sha,run.head_sha);},assertOriginalValidity:()=>{if(boundary.expired)throw Error('Original canonical artifact expired');}};}
const globals=globalThis as typeof globalThis&{admissionRuntimeBoundary?:typeof readCanonicalRuntimeJobsAndGuard;admissionSchemaBoundary?:typeof readCanonicalSchemaJobsAndGuard};globals.admissionRuntimeBoundary=readCanonicalRuntimeJobsAndGuard;globals.admissionSchemaBoundary=readCanonicalSchemaJobsAndGuard;
const boundaryHook=registerHooks({load(url,context,next){if(url.endsWith('/backend-release-admission.ts'))return{shortCircuit:true,format:'module',source:transformSync(readFileSync(new URL(url),'utf8').replace("from './canonical-runtime-jobs'","from './canonical-runtime-jobs?admission-wrapper-boundary'").replace("from './canonical-schema-jobs'","from './canonical-schema-jobs?admission-wrapper-boundary'"),{loader:'ts',format:'esm'}).code};if(url.includes('/canonical-runtime-jobs')&&url.endsWith('?admission-wrapper-boundary'))return{shortCircuit:true,format:'module',source:'export const readCanonicalRuntimeJobsAndGuard=globalThis.admissionRuntimeBoundary;'};if(url.includes('/canonical-schema-jobs')&&url.endsWith('?admission-wrapper-boundary'))return{shortCircuit:true,format:'module',source:'export const readCanonicalSchemaJobsAndGuard=globalThis.admissionSchemaBoundary;'};return next(url,context);}});
after(()=>{boundaryHook.deregister();delete globals.admissionRuntimeBoundary;delete globals.admissionSchemaBoundary;});
