async function zipReceipt(value:unknown,name='receipt.json'){const zip=new yazl.ZipFile(),parts:Buffer[]=[];const done=new Promise<Buffer>((resolve,reject)=>{zip.outputStream.on('data',chunk=>parts.push(chunk));zip.outputStream.on('error',reject);zip.outputStream.on('end',()=>resolve(Buffer.concat(parts)));});zip.addBuffer(Buffer.from(canonicalReleaseExecutionJson(value)),name);zip.end();return done;}
