test('native wrapper acquires one canonical proof per call and repeats current source founder and controls before returning',async()=>{const{readBackendReleaseAdmission}=await api();await fixture(async f=>{boundary.runtime=0;const result=await readBackendReleaseAdmission(f.input);assert.equal(boundary.runtime,1,'Immutable original canonical proof is acquired once per admission call.');assert.equal(result.provenance,'OFFICIAL_GITHUB_AND_VERIFIED_GIT_SOURCE');assert.equal(result.approval.state,'approved');assert.equal(result.expected.releaseSha,f.sha);assert.equal(result.expected.currentMainSha,f.sha);assert.equal(result.expected.treeSha,f.expected.treeSha);assert.equal(JSON.stringify(result).includes(token),false);assert.equal(JSON.stringify(result).includes('controlled-signature'),false);for(const path of ['git/ref/heads/main','actions/runs/51/approvals','environments/staging','branches/main/protection','branches/main/protection/required_signatures'])assert.equal(f.calls.filter(value=>value===path).length,path==='actions/runs/51/approvals'?4:3,path);await readBackendReleaseAdmission(f.input);assert.equal(boundary.runtime,2,'A new call reacquires proof; it never reuses earlier passing admission.');assert.equal(f.calls.filter(path=>path==='actions/runs/51/approvals').length,8);});});

test('prepared native admission reacquires current controls and source while retaining one immutable proof',async()=>{
 const subject=await api();assert.equal(typeof subject.prepareNativeBackendReleaseAdmission,'function');await fixture(async f=>{boundary.runtime=0;const handle=await subject.prepareNativeBackendReleaseAdmission(f.input),binding={repoRoot:f.input.repoRoot,prepared:f.input.prepared,expected:f.input.expected,effectScope:'COMPLETE_BACKEND'};assert.equal(boundary.runtime,1);const proofs=[];for(let index=0;index<3;index++)proofs.push(await subject.readNativeBackendReleaseAdmission(handle,binding));assert.equal(boundary.runtime,1,'Original immutable proof is acquired once for the held release');assert.equal(f.calls.filter(path=>path==='actions/runs/51/approvals').length,10,'Preparation and every refresh repeat actual current founder approval');assert.ok(proofs.every(value=>value.expected.releaseSha===f.sha&&value.provenance==='OFFICIAL_GITHUB_AND_VERIFIED_GIT_SOURCE'));subject.disposeNativeBackendReleaseAdmission(handle);await assert.rejects(subject.readNativeBackendReleaseAdmission(handle,binding));});
});
test('same complete-backend package keeps schema consumption and provider admission as distinct opaque scopes',async()=>{const subject=await api();await fixture(async f=>{const schemaInput={...f.input,effectScope:'SCHEMA_AND_SYNTHETIC_AUTH'},schemaBinding={repoRoot:f.input.repoRoot,prepared:f.input.prepared,expected:f.input.expected,effectScope:'SCHEMA_AND_SYNTHETIC_AUTH'},providerBinding={...schemaBinding,effectScope:'COMPLETE_BACKEND'},schema=await subject.prepareNativeBackendReleaseAdmission(schemaInput),provider=await subject.prepareNativeBackendReleaseAdmission(f.input);assert.notEqual(schema,provider);assert.equal((await subject.readNativeBackendReleaseAdmission(schema,schemaBinding)).expected.releaseSha,f.sha);assert.equal((await subject.readNativeBackendReleaseAdmission(provider,providerBinding)).expected.releaseSha,f.sha);await assert.rejects(subject.readNativeBackendReleaseAdmission(provider,schemaBinding));assert.equal((await subject.readNativeBackendReleaseAdmission(schema,schemaBinding)).expected.releaseSha,f.sha);subject.disposeNativeBackendReleaseAdmission(schema);subject.disposeNativeBackendReleaseAdmission(provider);});});

test('prepared native admission rejects cloned foreign bindings and revoked current evidence without reacquisition',async()=>{
 const subject=await api();assert.equal(typeof subject.prepareNativeBackendReleaseAdmission,'function');for(const mode of['clone','proxy','binding','approval','source','producer','expiry']as const)await fixture(async f=>{boundary.runtime=0;const handle=await subject.prepareNativeBackendReleaseAdmission(f.input),binding={repoRoot:f.input.repoRoot,prepared:f.input.prepared,expected:f.input.expected,effectScope:'COMPLETE_BACKEND'},calls=f.calls.length;let candidate:unknown=handle,request:unknown=binding;if(mode==='clone')candidate=structuredClone(handle);if(mode==='proxy')candidate=new Proxy(handle,{});if(mode==='binding')request={...binding,effectScope:'SCHEMA_AND_SYNTHETIC_AUTH'};if(mode==='approval')f.responses.set('actions/runs/51/approvals',[]);if(mode==='source')await writeFile(join(f.root,'README.md'),'Changed source after immutable proof\n');if(mode==='producer'){const page=f.responses.get('actions/runs/31/attempts/2/jobs?per_page=100&page=1')as {jobs:{name:string;conclusion:string}[]};page.jobs.find(row=>row.name==='runtime-backend')!.conclusion='failure';}if(mode==='expiry')boundary.expired=true;try{await assert.rejects(subject.readNativeBackendReleaseAdmission(candidate,request));if(['clone','proxy','binding','source'].includes(mode))assert.equal(f.calls.length,calls);assert.equal(boundary.runtime,1);if(['approval','source','producer','expiry'].includes(mode))await assert.rejects(subject.readNativeBackendReleaseAdmission(handle,binding),'A failed refresh cannot reuse its earlier proof');}finally{boundary.expired=false;subject.disposeNativeBackendReleaseAdmission(handle);}});
});

test('overlapping or disposed prepared reads invalidate both consumers before returning authority',async()=>{
 const subject=await api();await fixture(async f=>{const handle=await subject.prepareNativeBackendReleaseAdmission(f.input),binding={repoRoot:f.input.repoRoot,prepared:f.input.prepared,expected:f.input.expected,effectScope:'COMPLETE_BACKEND'},fetcher=globalThis.fetch;let started!:()=>void,release!:()=>void;const entered=new Promise<void>(done=>started=done),blocked=new Promise<void>(done=>release=done);let held=false;globalThis.fetch=async(raw,options)=>{if(!held&&String(raw).endsWith('/actions/runs/51')){held=true;started();await blocked;}return fetcher(raw,options);};const first=subject.readNativeBackendReleaseAdmission(handle,binding);await entered;await assert.rejects(subject.readNativeBackendReleaseAdmission(handle,binding));release();await assert.rejects(first);await assert.rejects(subject.readNativeBackendReleaseAdmission(handle,binding));subject.disposeNativeBackendReleaseAdmission(handle);});
 await fixture(async f=>{const handle=await subject.prepareNativeBackendReleaseAdmission(f.input),binding={repoRoot:f.input.repoRoot,prepared:f.input.prepared,expected:f.input.expected,effectScope:'COMPLETE_BACKEND'},fetcher=globalThis.fetch;let entered!:()=>void,release!:()=>void;const started=new Promise<void>(done=>entered=done),blocked=new Promise<void>(done=>release=done);let held=false;globalThis.fetch=async(raw,options)=>{if(!held&&String(raw).endsWith('/actions/runs/51')){held=true;entered();await blocked;}return fetcher(raw,options);};const pending=subject.readNativeBackendReleaseAdmission(handle,binding);await started;subject.disposeNativeBackendReleaseAdmission(handle);release();await assert.rejects(pending);});
});

