test('direct activation consumers require the current official successful activation step rather than matching local success bytes',async()=>{const subject=await api();assert.equal(typeof subject.readBackendActivationExecutionAdmission,'function');for(const mode of['success','failure','running','drift'])await fixture(async f=>{const started=new Date(Date.now()-1000).toISOString(),completed=new Date().toISOString(),job={id:70,name:'schema',run_id:51,run_attempt:1,head_sha:f.sha,head_branch:'main',status:'in_progress',conclusion:null,started_at:started,completed_at:null,steps:[{name:'Re-admit official founder package before private credentials',number:1,status:'completed',conclusion:'success',started_at:started,completed_at:completed},{name:'Verify signed worker execution and scheduled recovery',number:2,status:mode==='running'?'in_progress':'completed',conclusion:mode==='failure'?'failure':mode==='running'?null:'success',started_at:started,completed_at:mode==='running'?null:completed}]};f.responses.set('actions/runs/51/attempts/1/jobs?per_page=100&page=1',{total_count:1,jobs:[job]});const fetcher=globalThis.fetch;let reads=0;globalThis.fetch=async(url,options)=>{if(mode==='drift'&&String(url).includes('/actions/runs/51/attempts/1/jobs')&&++reads>1)job.steps[1].conclusion='failure';return fetcher(url,options);};if(mode==='success'){const result=await subject.readBackendActivationExecutionAdmission(f.input);assert.equal(result.activationStepVerified,true);assert.equal(result.jobId,70);assert.equal(JSON.stringify(result).includes(token),false);}else await assert.rejects(subject.readBackendActivationExecutionAdmission(f.input));});});

test('canonical runtime proof cannot survive a changed attempt skipped lane job or substituted retained digest',async()=>{
 const{readBackendReleaseAdmission}=await api();
 for(const mode of ['attempt','skip','digest'])await fixture(async f=>{
  if(mode==='attempt')f.responses.set('actions/runs/31',{...f.responses.get('actions/runs/31') as object,run_attempt:3});
  if(mode==='skip'){const jobs=f.responses.get('actions/runs/31/attempts/2/jobs?per_page=100&page=1') as {jobs:{steps:{conclusion:string}[]}[]};jobs.jobs[0].steps[5].conclusion='skipped';}
  if(mode==='digest')(f.expected.canonicalRuntimeVerification as {jobsSha256:string}).jobsSha256='0'.repeat(64);
  await assert.rejects(readBackendReleaseAdmission(f.input));
 });
});

test('failed official source signature run attempt environment or approval refuses admission with fixed private errors',async()=>{const{readBackendReleaseAdmission}=await api();for(const[path,value]of [['git/ref/heads/main',{object:{type:'commit',sha:'0'.repeat(40)}}],['actions/runs/31',{conclusion:'failure'}],['actions/runs/51',{run_attempt:2}],['environments/staging',{id:124,name:'staging'}],['branches/main/protection/required_signatures',{enabled:false}],['actions/runs/51/approvals',[]]]as [string,unknown][])await fixture(async f=>{f.responses.set(path,value);await assert.rejects(readBackendReleaseAdmission(f.input),/admission.*requires review/i);});await fixture(async f=>{f.responses.set(`git/commits/${f.sha}`,{sha:f.sha,tree:{sha:f.expected.treeSha},verification:{verified:false,reason:'unsigned',signature:null,payload:null}});await assert.rejects(readBackendReleaseAdmission(f.input));});});

