test('native focused admission re-reads every successful job and rejects proof drift before effects', async () => {
  const { readBackendReleaseAdmission } = await api();
  await fixture(async f => {
    const ci = { ...f.responses.get('actions/runs/31') as object, path: '.github/workflows/staging-verification.yml', event: 'workflow_dispatch', run_attempt: 1 };
    const jobs = Object.entries(stagingVerificationJobPolicy).map(([name, policy], index) => ({ id: index + 1, name, run_id: 31, run_attempt: 1,
      head_sha: f.sha, head_branch: 'main', status: 'completed', conclusion: 'success', steps: policy.steps.map((step, position) => ({ name: step, number: position + 1, status: 'completed', conclusion: 'success' })) }));
    f.responses.set('actions/runs/31', ci);
    f.responses.set('actions/runs/31/attempts/1/jobs?per_page=100&page=1', { total_count: jobs.length, jobs });
    const securityRun = { ...ci, id: 41, path: '.github/workflows/ci.yml', event: 'push' };
    f.responses.set(`actions/workflows/ci.yml/runs?branch=main&event=push&head_sha=${f.sha}&per_page=100&page=1`, { total_count: 1, workflow_runs: [securityRun] });
    f.responses.set('actions/runs/41', securityRun);
    const started=Date.now()-10000,completed=Date.now()-1000;
    const securitySteps = ['Run actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1','Run actions/setup-node@820762786026740c76f36085b0efc47a31fe5020','Run npm install --global npm@11.17.0 --ignore-scripts --no-audit --no-fund','Run npm ci --ignore-scripts --no-audit --no-fund','Run node node_modules/esbuild/install.js','Run github/codeql-action/init@2892aa5e19bbd11bc0cff5427e3b750a04d9e3c2','Run github/codeql-action/analyze@2892aa5e19bbd11bc0cff5427e3b750a04d9e3c2','Require current processed CodeQL security findings to be clear','Retain original processed CodeQL receipt'];
    f.responses.set('actions/runs/41/attempts/1/jobs?per_page=100&page=1', { total_count: 1, jobs: [{ id: 70, name: 'codeql', run_id: 41, run_attempt: 1, head_sha: f.sha, head_branch: 'main', status: 'completed', conclusion: 'success',started_at:new Date(started).toISOString(),completed_at:new Date(completed).toISOString(), steps: securitySteps.map((name,index)=>({ name, number: index+1, status:'completed', conclusion:'success' })) }] });
    const receipt={version:1,purpose:'ORIGINAL_PROCESSED_CODEQL_RECEIPT',policy:'CODEQL_MEDIUM_HIGH_CRITICAL_V1',repository:repo,sourceSha:f.sha,ref:'refs/heads/main',runId:'41',runAttempt:1,observedAt:new Date(started+5000).toISOString(),analysis:{id:20,sarifId:'01234567-89ab-cdef-0123-456789abcdef',key:'.github/workflows/ci.yml:codeql',toolVersion:'2.27.1',createdAt:new Date(started+1000).toISOString()},result:{check:'codeql-open-security-alerts',status:'VERIFIED',analysisResults:0,analysisRules:87,openAlerts:0,blockingAlerts:0,severities:{low:0,medium:0,high:0,critical:0,nonsecurity:0},snapshotPasses:2}};
    const archive=await zipReceipt(receipt);
    f.responses.set('actions/runs/41/artifacts?per_page=100',{total_count:1,artifacts:[{id:72,name:'cuevo-codeql-41-1',size_in_bytes:archive.length,expired:false,digest:'sha256:'+createHash('sha256').update(archive).digest('hex'),created_at:new Date(started+6000).toISOString(),expires_at:new Date(Date.now()+86400000).toISOString(),workflow_run:{id:41,head_sha:f.sha,head_branch:'main'}}]});
    const fetcher=globalThis.fetch;let archiveReads=0;globalThis.fetch=async(url,options)=>{if(String(url).endsWith('/actions/artifacts/72/zip')){archiveReads++;return new Response(new Uint8Array(archive));}return fetcher(url,options);};
    const jobProof = await readStagingVerificationJobs(ci, async path => f.responses.get(path),async()=>archive);
    assert.ok(jobProof);
    const stagingVerification = { scope: 'SCHEMA_AND_SYNTHETIC_AUTH', ...jobProof };
    const expected = { ...f.expected, ciRun: ci, stagingVerification, executionScope: 'schema-and-accounts' }; delete (expected as Record<string,unknown>).canonicalRuntimeVerification;
    const body = JSON.parse((f.input.prepared as { canonicalJson: string }).canonicalJson);
    delete body.canonicalRuntimeVerification;
    const prepared = prepareBackendReleaseIntent({ ...body, stagingVerification, executionScope: 'schema-and-accounts' }, expected);
    f.responses.set('actions/runs/51/approvals', [{ environments: [{ id: 123, name: 'staging' }], state: 'approved', user: { id: 95836629, login: 'attaulhaq0', type: 'User' }, comment: prepared.comment }]);
    const input = { ...f.input, expected, prepared, effectScope: 'SCHEMA_AND_SYNTHETIC_AUTH' };
    await assert.rejects(readBackendReleaseAdmission({ ...input, effectScope: 'COMPLETE_BACKEND' }));
    await assert.rejects(readBackendReleaseAdmission({ ...f.input, expected, prepared }));
    assert.equal(f.calls.length, 0);
    archiveReads=0;
    const admitted = await readBackendReleaseAdmission(input);
    assert.deepEqual(admitted.expected.stagingVerification, stagingVerification);
    assert.equal(archiveReads,1,'The original focused security ZIP is acquired once; only original metadata is repeated');
    assert.equal(f.calls.filter(path => path.startsWith('actions/runs/31/attempts/1/jobs')).length, 3);
    const guardedFetcher=globalThis.fetch;let approvalReads=0;globalThis.fetch=async(url,options)=>{const response=await guardedFetcher(url,options);if(String(url).endsWith('/approvals')&&++approvalReads===2)jobs[0].steps[0].conclusion='skipped';return response;};
    await assert.rejects(readBackendReleaseAdmission(input),'Late focused job drift must fail metadata guard');globalThis.fetch=guardedFetcher;jobs[0].steps[0].conclusion='success';
    const expiryFetcher=globalThis.fetch;approvalReads=0;globalThis.fetch=async(url,options)=>{const response=await expiryFetcher(url,options);if(String(url).endsWith('/approvals')&&++approvalReads===2){const page=f.responses.get('actions/runs/41/artifacts?per_page=100')as{artifacts:{expired:boolean}[]};page.artifacts[0].expired=true;}return response;};await assert.rejects(readBackendReleaseAdmission(input),'Late original focused artifact expiry must fail metadata guard');
  });
});
